INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Behind The Truth', 'Have you ever be deceived by a stranger on the internet? Have you ever seen those exposed college girl’s nude-photos as they can’t repays the loan? You will play as a female journalist, to disclose all the danger and crime which underlie the depths of society and awaken more women.The game is based on a true story, and it has been reported in Southern Weekend on 7th July 2017.' FROM games WHERE igdb_id = 83954 ON CONFLICT (game_id, language_code) DO NOTHING;
