INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chiki-chiki-boxy-racers', 107229, '2018-08-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7yg0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbak.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chiki-Chiki Boxy Racers', 'Drift like a pro with easy analog stick controls! The intuitive party battle mode offers fun for everyone. Play wherever you are, any time! A mode with separate steering and accelerating/braking controls is also available. Compete with up to 8 players in multiplayer mode! - Shared Play using only Joy-Con controllers. - Local Multiplayer with each user playing on their own Nintendo Switch. - Online Multiplayer where you compete against global opponents. - Each mode can be played with 2-8 players. - Race Mode - There are four race tracks for each of the city, jungle and beach areas, making a total of 12 tracks! Win races to unlock new vehicles. There are 20 amazing vehicles to unlock, each with different features! - Party Battle Mode - You''ll be spoilt for choice with four party game modes! - COINS - Collect coins that appear on the stage. Try for the jackpot playing the slots! - SMASH - Smash into opponents and push them off the stage. Drop 5 times and you''re out! - PAINT - Paint the stage, claiming your turf. The player with the biggest turf wins! - GOAL - Get the ball into the opposing team''s goal to score. Good teamplay is key to winning!' FROM games WHERE igdb_id = 107229 ON CONFLICT (game_id, language_code) DO NOTHING;
