INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Hard', 'Dream Hard is a short two-player co-op queer-themed beat ''em up game. In it, you must defend the local NYC queer performance space The Dreamhouse from hordes of fascists. The retro-style 3D graphics imagine a history of queer punk games in the late 1990s, connecting those politics of resistance to today.' FROM games WHERE igdb_id = 184912 ON CONFLICT (game_id, language_code) DO NOTHING;
