INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Road Trip USA', 'Take a road trip across the beautiful landscape of the United States of America in this relaxing classic hidden object game. Challenge yourself with fun puzzle mini games like Match 3, Mahjong, Block slide and Spot the Differences. Travel through 20 stunning scene locations as you play multiple hidden object modes: word, riddle, silhouette, night mode, missing vowels and scramble.' FROM games WHERE igdb_id = 88342 ON CONFLICT (game_id, language_code) DO NOTHING;
