INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('japanese-rail-sim-3d-5-types-of-trains', 147915, '2018-11-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co599a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1izr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Japanese Rail Sim 3D: 5 types of trains', 'Drive the Ohmi Railway, The oldest existing private railway in Shiga prefecture! Now with five different passenger trains to drive! This game introduces the oldest existing private railway of Japan. The Ohmi Railway is, just as its headquarters, located in Shiga prefecture. Locals call it the "Gacha-kon train", from the sound of the when train rumbling over the railroad tracks. The Ohmi Railway is a long distance railway split into four sections that connects the east side of Biwako lake from north to south. You will drive the main line, which is the 47.7km from Maibara station to Kibukawa station. On the wayside, there are many tourist spots and historic sites such as Hikonejyo. You will feel like a traveler while driving past those spots in Ohmi''s townscape and the countryside. There are five exclusive types of trains to drive! Try to unlock all of them by getting a good score. Each train has its own unique characteristics, looks, and sounds.' FROM games WHERE igdb_id = 147915 ON CONFLICT (game_id, language_code) DO NOTHING;
