INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wars of Succession', 'Ageod''s Wars of Succession is a strategic game designed to cover two major wars that consumed Europe at the eve of the 18th Century, the Spanish Succession (1701-1713), and the Great Northern War (1700-1721). Play out these two historical wars across a huge map, divided into 5,000 regions, across 5 different scenarios. Choose your battlefield tactics carefully, your decisions can turn the tide of battle.' FROM games WHERE igdb_id = 79814 ON CONFLICT (game_id, language_code) DO NOTHING;
