INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Twiggles VR', 'A 3D puzzle game designed specifically for VR. Immerse yourself in the unique world of the Twiggles and enjoy hours of mind-blowing, brain-twisting, puzzle-solving fun. Get creative and design your own puzzles with the built-in VR editor and earn points for twisting the brains of your friends.' FROM games WHERE igdb_id = 107508 ON CONFLICT (game_id, language_code) DO NOTHING;
