INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paroniria', '一个小女孩被卷入了一连串诡异的事件，信仰，争端，神秘空间----究竟她的命运会如何呢？ 本游戏为多结局模式，玩家需要收集信息和道具来触发不同的结局。 《梦缚》 是一款剧情向游戏，带有部分解谜和迷宫玩法，希望大家会喜欢！ 老梅如果有空会持续更新，如果大家发现一些问题请向梅老师提出，梅老师会尽量修复。 希望大家能不嫌弃我们刚刚起步的革诚星迹团队。' FROM games WHERE igdb_id = 111095 ON CONFLICT (game_id, language_code) DO NOTHING;
