INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Volotic', 'Volotic is an experimental nonlinear sequencer by artist Scott Garner. What does that even mean? It means a fun way to create songs for everyone, with no musical experience required. In Volotic, you compose a song by arranging a selection of "towers" on a grid. Each tower has a different function for creating beats, modifying beats or triggering instruments.' FROM games WHERE igdb_id = 89439 ON CONFLICT (game_id, language_code) DO NOTHING;
