INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thy Knights of Climbalot', 'A fast paced, heart throbbing racing/climbing game where you alone, or with friends, do what the knights of climbalot does best... Climbing! Race against time in over 30 single player levels, each with their own challanges and dangerous surroundings for you to overcome!Race against your friends and find out whom of you are worthy of the title, climb master, in three different enviroment. Each with adjustable difficulties!Do not just relly on your own skill!Use different power-ups and enviromental hazards to your advantage. And if that fails? Simply punch your opponents in the face!' FROM games WHERE igdb_id = 109675 ON CONFLICT (game_id, language_code) DO NOTHING;
