INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nowhere: Lost Memories', 'Nowhere: Lost Memories is a first person mystery adventure with touches of terror. An immersive game about exploration and discovery that will puts you in the role of a mysterious character who will have to delve into a strange place exploring each area and solving the different enigmas in order to discover the truth. But something dark hides behind this place, you are not the only one who has been here before.' FROM games WHERE igdb_id = 96166 ON CONFLICT (game_id, language_code) DO NOTHING;
