INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fever Golf', 'This is a game about early 2000s bargain bin CD culture, that is, games that few people played & fewer remember. They were the last few digital artifacts that were allowed to fall into the quiet oblivion of history—the rear guard of an older era that pre-existed our current climate of perpetual distribution. This is a game for the MySimAquariam and MoonTycoons of the world; bottom-shelf junk-ware with a soul.' FROM games WHERE igdb_id = 314137 ON CONFLICT (game_id, language_code) DO NOTHING;
