INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lifty!', 'Welcome to the Lifty Tower! Deliver the passengers to their colored floors and climb the tower in this fun and addictive elevator game! Can you get to the top and claim the title of the Lifty King?! Thrust up or down to move your lift. Pick up passengers and deliver them to the floor that matches their color before they explode. It’s easy to pick up, but gets challenging when new passengers with different characteristics are unlocked as you progress!' FROM games WHERE igdb_id = 113581 ON CONFLICT (game_id, language_code) DO NOTHING;
