INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mazm-the-phantom-of-the-opera', 125865, '2018-03-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3nr5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arclx.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MazM: The Phantom of the Opera', 'The French gothic horror novel "The Phantom of the Opera" (1910) revisits modern audience as "MazM: The Phantom of the Opera", the adventure game for the Nintendo Switch! Decades after the "Phantom of the Opera" case that shook the Parisian opera house, a detective visits the place to uncover the truth about the Phantom. Find out what secret is hidden in the opera house by collecting footnotes and investigating characters! "He" is everywhere. "He" can see everything. And "he" is watching you…. Witness the shocking event about burning love and hate. Dive deep into the unique aesthetics depicting Belle Époque Paris of the late 19th Century and its people! Listen to the classical-style music that adds immersion to the lore! Enter the opera house, and see the mysterious and uncanny love story of the original novel turned more colorful and mesmerizing by MazM: The Phantom of the Opera!' FROM games WHERE igdb_id = 125865 ON CONFLICT (game_id, language_code) DO NOTHING;
