INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crush--1', 102296, '2018-05-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2s52.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc90w3.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crush', 'Crush is a classic twin stick shooter game with a heavy focus on arena fighting. Inspired by Smash TV, visuals and game play were created to capture the authentic retro feel. Play as a contestant (in single player or local co-op) on the greatest show on earth. You will navigate through multiple arenas, acquire new weapons, use powerful items, and win amazing cash and prizes... The only problem is, you have to survive.' FROM games WHERE igdb_id = 102296 ON CONFLICT (game_id, language_code) DO NOTHING;
