INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Martha Madison: Magnetism', 'In Martha Madison: Magnetism, Martha needs your help to bring power to a nearby village of animals! There are rumors of an ancient power-generating machine hidden in a temple in the jungle, which works using properties of magnetism. Explore the temple, learn about magnetic fields, and place magnets in the correct spots to open the way deeper into the temple.' FROM games WHERE igdb_id = 83959 ON CONFLICT (game_id, language_code) DO NOTHING;
