INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bolt Riley: A Reggae Adventure', 'Bolt Riley is a a classic 2D point and click Jamaican Reggae adventure game where you play as Bolt Riley, a poor boy from Trenchtown, Jamaica, on his pathway to stardom. Bolt is struggling to survive and has to deal with a gang of Rude Boys. The game features hand drawn 2D background artwork and hand drawn cel animation. It combines all the elements of a classic point and click adventure game and includes funny dialog puzzles, exploration, wacky inventory items, and of course, a rope. Bolt can use special Inspirational powers he learned during his journeys.' FROM games WHERE igdb_id = 89052 ON CONFLICT (game_id, language_code) DO NOTHING;
