INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-search-for-salmon', 315637, '2018-06-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8rua.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctsih.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Search for Salmon', 'The Search for Salmon is an expert-level Kaizo. The aim of this hack isn''t to troll or torture the player, but rather to provide an extremely difficult challenge in a fair and interesting way. Players will need to employ a wide range of Kaizo and Item Abuse skills. Shell, spring, and p-switch tricks are used alongside tight platforming and jump control. Beginners will likely be very frustrated, but seasoned players will hopefully find a fresh, fun challenge. There are however, a few Kaizo boxes (both marked and un-marked) and few tricks and traps along the way. The game also features optional coins to collect for "100%" runs, and some secret rooms and surprises to discover. There''s even a checkpoint-save room so console players can rest without fear of losing any progress! Extensive play-testing has been done by myself and others to confirm that the entire game is indeed RTA-viable. I hope you enjoy it!INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 315637 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 315637 AND c.slug = 'glitchcat7' ON CONFLICT DO NOTHING;
