INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Reckoning: Sleight', 'Solve the murder of a renowned magician in this spectacular Hidden Object adventure! You’ve been invited to watch the world-famous Amazing Garibaldi Brothers perform their latest illusion for the grand opening of the new Stevens Tower Hotel. But when one of them is found dead backstage, it falls on your shoulders to track down and unmask the killer. Find the clues through incredible puzzles and mini-games in a race against time to stop an evil villain before he strikes again. Are you up to the challenge?' FROM games WHERE igdb_id = 87872 ON CONFLICT (game_id, language_code) DO NOTHING;
