INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guide', 'GUIDE is a 2D puzzle platformer game for children and youth that seeks to promote awareness and understanding of anxiety. Gameplay consists of helping Fia, a baby phoenix chick, escape a dark forest after she is knocked out of her nest be a ferocious storm. Players encourage Fia and her inner voice to challenge the shadows that plague them, fighting their fears and learning to cope with their anxieties in a compassionate way.' FROM games WHERE igdb_id = 109243 ON CONFLICT (game_id, language_code) DO NOTHING;
