INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Art Theft by Jay Doherty', 'The Art Theft by Jay Doherty is an interactive VR narrative that injects 3D drawings created by the user into the unfolding narrative of a reimagined "Mad Libs" experience. Go down a rabbit hole with Butch the Bear, Wesley the Wolf, and Mr. Maple the Goat, who make you feel like you''re on a classic heist.' FROM games WHERE igdb_id = 113131 ON CONFLICT (game_id, language_code) DO NOTHING;
