INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Wild', 'Something’s gone awry out West! Help Dusty Argile adventure out and defeat the baddies who are causing a commotion and stopping him from getting a good night’s rest. Put them to sleep with your handy lasso and rack up as many points as you can, but watch out for falling barrels, cacti, whirling tumbleweeds, snakes, and coyotes! Most of all, watch out for the mad bull and crazy Texan twister!' FROM games WHERE igdb_id = 228279 ON CONFLICT (game_id, language_code) DO NOTHING;
