INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Earth Dies Screaming', 'You pilot a defense ship in orbit above Earth. Destroy the invaders as they kamikaze into the atmosphere in an attempt to eliminate your precious home world. When (not if) the Earth''s shields run out of energy or your ship is destroyed, the planet goes "bye-bye". You can restore your energy by finding and destroying an enemy attack base. The only way to find one of those is by following a returning fighter to the base.' FROM games WHERE igdb_id = 40614 ON CONFLICT (game_id, language_code) DO NOTHING;
