INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swordfight', 'This game was finished at MNetwork in the 1980''s, but not released until much later. In 2000, Intellivision Productions released this game complete with a simple box and manual. It is still available from their web site. Swordfight requires two players, which is possibly why the game was not released in the first place.' FROM games WHERE igdb_id = 40794 ON CONFLICT (game_id, language_code) DO NOTHING;
