INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Immortal Love: Kiss of the Night', 'When your beloved falls ill, you''ll do anything to save her. You quickly discover that the price is much higher than you thought when you awake to find yourself in a coffin and your love has been kidnapped! Stuck in the middle of a war between the Hunters and Vampires, it''s up to you to find out why the Vampire Master wants your beloved and save her before it''s too late! Do you have what it takes?' FROM games WHERE igdb_id = 120796 ON CONFLICT (game_id, language_code) DO NOTHING;
