INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Expedia Cenote Experience', 'Explore the Cenote in Expedia Labs VR. The experience takes you into the caves of similar cenotes that are found in the Yucatan Peninsula. Although a simulation of the true experience, you can learn facts and where you could find real cenotes if you wish to travel in the future. Step into the water to watch the fish swim around you or stand on rocks as the waterfall gently splashes your face.' FROM games WHERE igdb_id = 109626 ON CONFLICT (game_id, language_code) DO NOTHING;
