INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steampunk Idle Spinner', 'A world of mad science and incredible contraptions is waiting for you! All what you have in your workshop at first is an ingenious machine, which produces coins as you spin the cogwheel. Earn money to upgrade it, to buy more cogs and gear, such as engines, pumps, hammers or wagons. Think as an engineering genius and you''ll become an ultimate tycoon.' FROM games WHERE igdb_id = 116243 ON CONFLICT (game_id, language_code) DO NOTHING;
