INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spot the Difference', 'From the original creators of the World famous Spot-The-Difference amusement machine game we bring you Spot-The-Difference on NINTENDO SWITCH, a TWO player version so you can play head to head against anyone, anytime. This special edition of Spot-The-Difference has the same exciting game play as the original amusement machine game and just like the amusement machine It will take sharp eyes and quick wits to uncover all the differences before you opponent or against the clock in single player mode.' FROM games WHERE igdb_id = 89080 ON CONFLICT (game_id, language_code) DO NOTHING;
