INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Piffle', 'The nefarious Doc Block has kidnapped Waffles the dog as part of his evil plans for world domination. Break Doc Block’s baffling blocks and help Piffle rescue Waffles the puppy with nothing more than your wits, your Piffle Balls and your favourite onesie! Smash through blocks that Doc Block has left to block your path! Be guided through the worlds of Pifflandia by quirky and interesting, selfie-loving characters including the eggstatic Detective Hard Boiled and Mooshi the frightened mushroom.' FROM games WHERE igdb_id = 110423 ON CONFLICT (game_id, language_code) DO NOTHING;
